typedef unsigned int big_int;

class string_buf
{
public:
  big_int *data;
  int max_blocks;
  int block_length;
  int char_length;
  int ref_count;

  inline int compare(const char *str) const
  {
    int i;
    const char *a = reinterpret_cast<const char *>(data);
    for (i = 0; i < char_length; i++) {
      if (str[i] == '\0') return -1;
      if (a[i] == str[i]) continue;
      if (str[i] > a[i]) return 1;
      if (str[i] < a[i]) return -1;
    }
    if (str[i] == '\0') return 0;
    return 1;
  }

  inline bool is_equal(const char *str) const
  {
    return (compare(str) == 0);
  }
};

class stringx
{
  friend inline bool operator==(const stringx& lhs, const char *rhs);
protected:
  char *chars;
  string_buf *my_buf;
public:
  ~stringx();
};

inline bool operator==(const stringx& lhs, const char *rhs)
{
  return lhs.my_buf->is_equal(rhs);
}

class filespec
{
public:
  stringx path;
  stringx name;
  stringx ext;
  explicit filespec(const stringx& s);
};

class scene_anim
{
public:
  void load(const stringx& filename);
private:
  void text_load(const stringx& filename);
  void binary_load(const stringx& filename);
};

void scene_anim::load( const stringx& filename )
{
  filespec spec( filename );

  if( spec.ext == ".snm" || spec.ext == ".SNM" ) {
    text_load( filename );
  } else {
    binary_load( filename );
  }

}
